39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    public abstract OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
45	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
46	     * email or householdId contributes an empty segment.
47	     */
48	    protected String identityKey(Owner owner) {
49	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
50	        String email = owner.getEmail() == null ? "" : owner.getEmail();
51	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
52	        return telephone + "|" + email + "|" + householdId;
53	    }
54	
55	    /**
56	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
57	     * present, otherwise {@code PHONE}.
58	     */
59	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
60	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
61	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
62	    }
63	
64	    /**
65	     * Derives the owner's locality (region) from the city using the fixed city-to-region
66	     * table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), returning {@code UNKNOWN} when the
67	     * city is not in the table.
68	     */
69	    protected String locality(Owner owner) {
70	        String city = owner.getCity();
71	        if (city == null) {
72	            return "UNKNOWN";
73	        }
74	        return switch (city) {
75	            case "Sydney" -> "NSW";
76	            case "Melbourne" -> "VIC";
77	            case "Brisbane" -> "QLD";
78	            default -> "UNKNOWN";
79	        };
80	    }
81	
82	    /**
83	     * The highest membership level derivable on creation. Level 4 is reserved for tenure and is
84	     * not assigned here.
85	     */
86	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
87	
88	    /**
89	     * Derives the owner's membership level, a number from 1 to {@value #MAX_MEMBERSHIP_LEVEL}:
90	     * it starts at 1, gains 1 when an email is present, and gains 1 when the owner has no
91	     * namesakes (namesakeCount is 0), capped at {@value #MAX_MEMBERSHIP_LEVEL}.
92	     */
93	    protected Integer membershipLevel(Owner owner) {
94	        int level = 1;
95	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
96	        if (hasEmail) {
97	            level++;
98	        }
99	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
100	        if (noNamesakes) {
101	            level++;
102	        }
103	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
104	    }
105	
106	    /**
107	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
108	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
109	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
110	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
111	     * owner has no registration date.
112	     */
113	    protected Boolean bulkSignupWarning(Owner owner) {
114	        LocalDate registrationDate = owner.getRegistrationDate();
115	        if (registrationDate == null) {
116	            return false;
117	        }
118	        long othersOnDay = this.clinicService.findAllOwners().stream()
119	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
120	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
121	            .count();
122	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
123	    }
