17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.Map;
28	import java.util.regex.Pattern;
29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
46	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
47	import org.springframework.samples.petclinic.rest.api.OwnersApi;
48	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
49	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.PetDto;
51	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
74	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
81	     * new owner's id, customerCode, registrationDate and membershipLevel.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Common street-type abbreviations expanded during address normalization, keyed by the
87	     * upper-cased abbreviation.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
90	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
91	
92	    /**
93	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
94	     * city already holds this many owners.
95	     */
96	    private static final int CITY_CAPACITY = 50;
97	
98	    /**
99	     * Maximum number of owners that may be created on a single day. A create is rejected once this
100	     * many owners already carry the current day as their {@code registrationDate}.
101	     */
102	    private static final int DAILY_OWNER_LIMIT = 100;
103	
104	    private final ClinicService clinicService;
105	
106	    private final OwnerMapper ownerMapper;
107	
108	    private final PetMapper petMapper;
109	
110	    private final VisitMapper visitMapper;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        validateRequiredFields(ownerFieldsDto);
151	        HttpHeaders headers = new HttpHeaders();
152	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
153	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
154	        LocalDate effectiveDate = owner.getRegistrationDate() == null
155	            ? LocalDate.now()
156	            : owner.getRegistrationDate();
157	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
158	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
159	        rejectWhenCityAtCapacity(owner.getCity());
160	        applyHousehold(owner);
161	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        rejectDuplicateIdentity(owner);
164	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
165	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
166	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
167	        this.clinicService.saveOwner(owner);
168	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
169	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
171	            ownerDto.getMembershipLevel());
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
179	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
180	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
181	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
182	     *
183	     * @param city     the owner's city
184	     * @param lastName the owner's last name
185	     * @return the assigned customer code
186	     */
187	    private String nextCustomerCode(String city, String lastName) {
188	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
189	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
190	        int sequence = (int) this.clinicService.findAllOwners().stream()
191	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
192	            .count() + 1;
193	        return String.format("%s-%s-%04d", city3, last3, sequence);
194	    }
195	
196	    /**
197	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
198	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
199	     *
200	     * @param customerCode     the owner's assigned customer code
201	     * @param registrationDate the owner's registration date
202	     * @return the assigned membership number
203	     */
204	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
205	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
206	    }
207	
208	    /**
209	     * Counts the existing owners that already share the given firstName and lastName, compared
210	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
211	     * the owners that pre-existed this create.
212	     *
213	     * @param firstName the new owner's first name
214	     * @param lastName  the new owner's last name
215	     * @return the number of existing namesakes
216	     */
217	    private int countNamesakes(String firstName, String lastName) {
218	        return (int) this.clinicService.findAllOwners().stream()
219	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
220	                && equalsIgnoreCase(existing.getLastName(), lastName))
221	            .count();
222	    }
223	
224	    /**
225	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
226	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
227	     * customer-code sequence is derived.
228	     *
229	     * @param city the new owner's city
230	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
231	     */
232	    private void rejectWhenCityAtCapacity(String city) {
233	        long count = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
235	            .count();
236	        if (count >= CITY_CAPACITY) {
237	            throw new CityAtCapacityException(city);
238	        }
239	    }
240	
241	    /**
242	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
243	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
244	     * business-day registration date, so the limit is enforced per business day and weekend
245	     * requests count against the Monday they roll forward to.
246	     *
247	     * @param registrationDate the owner's adjusted (business-day) registration date
248	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
249	     *                                  registration date
250	     */
251	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
252	        long count = this.clinicService.findAllOwners().stream()
253	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
254	            .count();
255	        if (count >= DAILY_OWNER_LIMIT) {
256	            throw new DailyOwnerLimitException(registrationDate);
257	        }
258	    }
259	
260	    /**
261	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
262	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
263	     * effective registration date (whether supplied in the request or defaulted to the server date)
264	     * so a weekend value never persists as an owner's {@code registrationDate}.
265	     *
266	     * @param date the effective registration date
267	     * @return the same date when it is a weekday, otherwise the next Monday
268	     */
269	    private LocalDate toBusinessDay(LocalDate date) {
270	        return switch (date.getDayOfWeek()) {
271	            case SATURDAY -> date.plusDays(2);
272	            case SUNDAY -> date.plusDays(1);
273	            default -> date;
274	        };
275	    }
276	
277	    private boolean equalsIgnoreCase(String a, String b) {
278	        return a == null ? b == null : a.equalsIgnoreCase(b);
279	    }
280	
281	    /**
282	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
283	     * offending field so the client learns about all of them at once.
284	     *
285	     * @param ownerFieldsDto the submitted owner fields
286	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
287	     *                                     missing or blank
288	     */
289	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
290	        List<String> errors = new ArrayList<>();
291	        if (isBlank(ownerFieldsDto.getFirstName())) {
292	            errors.add("firstName");
293	        }
294	        if (isBlank(ownerFieldsDto.getLastName())) {
295	            errors.add("lastName");
296	        }
297	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
298	            errors.add("address");
299	        }
300	        if (isBlank(ownerFieldsDto.getCity())) {
301	            errors.add("city");
302	        }
303	        if (isBlank(ownerFieldsDto.getTelephone())) {
304	            errors.add("telephone");
305	        }
306	        if (!errors.isEmpty()) {
307	            throw new MissingOwnerFieldsException(errors);
308	        }
309	    }
310	
311	    private boolean isBlank(String value) {
312	        return value == null || value.isBlank();
313	    }
314	
315	    /**
316	     * The number of national (subscriber) digits an E.164 number must carry for a given country
317	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
318	     * national digits and the North American Numbering Plan ('+1') requires 10.
319	     */
320	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
321	        Map.of("61", 9, "1", 10);
322	
323	    /**
324	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
325	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
326	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
327	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
328	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
329	     *
330	     * @param telephone the raw telephone value as submitted
331	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
332	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
333	     *                                   national-number length is wrong for its country code
334	     */
335	    private String normalizeTelephone(String telephone) {
336	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
337	        String nationalSignificantNumber;
338	        if (cleaned.startsWith("+")) {
339	            nationalSignificantNumber = cleaned.substring(1);
340	        } else {
341	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
342	            nationalSignificantNumber = "61" + national;
343	        }
344	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
345	            throw new InvalidTelephoneException(telephone);
346	        }
347	        validateNationalNumberLength(nationalSignificantNumber, telephone);
348	        return "+" + nationalSignificantNumber;
349	    }
350	
351	    /**
352	     * Validates the national-number length of an E.164 number against its country calling code. The
353	     * significant number is a country code immediately followed by the national digits; for each
354	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
355	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
356	     * left unchecked.
357	     *
358	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
359	     * @param rejectedValue             the raw telephone value, reported on rejection
360	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
361	     */
362	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
363	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
364	            String countryCode = rule.getKey();
365	            if (nationalSignificantNumber.startsWith(countryCode)) {
366	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
367	                if (nationalDigits != rule.getValue()) {
368	                    throw new InvalidTelephoneException(rejectedValue);
369	                }
370	                return;
371	            }
372	        }
373	    }
374	
375	    /**
376	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
377	     * value is treated as absent and returns {@code null}); when present the value must be a
378	     * syntactically valid address, and is stored and returned lower-cased.
379	     *
380	     * @param email the raw email value as submitted, may be {@code null}
381	     * @return the lower-cased email, or {@code null} when none was supplied
382	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
383	     */
384	    private String normalizeEmail(String email) {
385	        if (email == null || email.isBlank()) {
386	            return null;
387	        }
388	        String normalized = email.trim().toLowerCase();
389	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
390	            throw new InvalidEmailException(email);
391	        }
392	        return normalized;
393	    }
394	
395	    /**
396	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
397	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
398	     * key is the normalized telephone, email and householdId joined together, this one check
399	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
400	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
401	     * with different telephones have different keys and are both allowed.
402	     *
403	     * @param owner the owner being created, with its normalized telephone, email and householdId
404	     *              already applied
405	     * @throws DuplicateIdentityException if another owner already has the same identityKey
406	     */
407	    private void rejectDuplicateIdentity(Owner owner) {
408	        String identityKey = identityKey(owner);
409	        boolean inUse = this.clinicService.findAllOwners().stream()
410	            .map(this::identityKey)
411	            .anyMatch(identityKey::equals);
412	        if (inUse) {
413	            throw new DuplicateIdentityException(identityKey);
414	        }
415	    }
416	
417	    /**
418	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
419	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
420	     * duplicate decision is made by comparing whole identityKeys.
421	     *
422	     * @param owner the owner whose identityKey to derive
423	     * @return the derived identityKey
424	     */
425	    private String identityKey(Owner owner) {
426	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
427	        String email = owner.getEmail() == null ? "" : owner.getEmail();
428	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
429	        return telephone + "|" + email + "|" + householdId;
430	    }
431	
432	    /**
433	     * Applies the household rule to an owner being created. An owner belongs to the same household
434	     * as an existing owner when their lastName and address both match (compared case-insensitively
435	     * with runs of whitespace collapsed to a single space).
436	     *
437	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
438	     * every existing owner in the household are assigned the same stable
439	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
440	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
441	     * which the householdId is one segment, so two members of the same household with different
442	     * telephones have different keys and are both allowed.
443	     *
444	     * @param owner the owner being created
445	     */
446	    private void applyHousehold(Owner owner) {
447	        String lastNameKey = toHouseholdKey(owner.getLastName());
448	        String addressKey = toHouseholdKey(owner.getAddress());
449	        List<Owner> household = this.clinicService.findAllOwners().stream()
450	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
451	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
452	            .toList();
453	        if (household.isEmpty()) {
454	            return;
455	        }
456	        String householdId = householdId(lastNameKey, addressKey);
457	        owner.setHouseholdId(householdId);
458	        for (Owner existing : household) {
459	            if (!householdId.equals(existing.getHouseholdId())) {
460	                existing.setHouseholdId(householdId);
461	                this.clinicService.saveOwner(existing);
462	            }
463	        }
464	    }
465	
466	    /**
467	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
468	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
469	     * lastName and address keys. Being a pure function of the household, every owner in it derives
470	     * the same value regardless of creation order.
471	     *
472	     * @param lastNameKey the normalized household lastName key
473	     * @param addressKey  the normalized household address key
474	     * @return the household identifier
475	     */
476	    private String householdId(String lastNameKey, String addressKey) {
477	        try {
478	            byte[] digest = MessageDigest.getInstance("SHA-256")
479	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
480	            StringBuilder hex = new StringBuilder(digest.length * 2);
481	            for (byte b : digest) {
482	                hex.append(String.format("%02x", b));
483	            }
484	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
485	        } catch (NoSuchAlgorithmException ex) {
486	            throw new IllegalStateException("SHA-256 not available", ex);
487	        }
488	    }
489	
490	    /**
491	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
492	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
493	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
494	     * string.
495	     */
496	    private String toHouseholdKey(String value) {
497	        if (value == null) {
498	            return "";
499	        }
500	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
501	    }
502	
503	    /**
504	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
505	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
506	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
507	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
508	     * value, or one that is blank once trimmed, normalizes to an empty string.
509	     *
510	     * @param address the raw address value as submitted, may be {@code null}
511	     * @return the normalized address, or an empty string when none was supplied
512	     */
513	    private String normalizeAddress(String address) {
514	        if (address == null) {
515	            return "";
516	        }
517	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
518	        if (collapsed.isEmpty()) {
519	            return "";
520	        }
521	        String[] tokens = collapsed.split(" ");
522	        StringBuilder normalized = new StringBuilder(collapsed.length());
523	        for (int i = 0; i < tokens.length; i++) {
524	            if (i > 0) {
525	                normalized.append(' ');
526	            }
527	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
528	        }
529	        return normalized.toString();
530	    }
531	
532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Override
534	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
535	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
536	        if (currentOwner == null) {
537	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
538	        }
539	        currentOwner.setAddress(ownerFieldsDto.getAddress());
540	        currentOwner.setCity(ownerFieldsDto.getCity());
541	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
542	        currentOwner.setLastName(ownerFieldsDto.getLastName());
543	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
544	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
545	        this.clinicService.saveOwner(currentOwner);
546	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
547	    }
548	
549	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
550	    @Transactional
551	    @Override
552	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
553	        Owner owner = this.clinicService.findOwnerById(ownerId);
554	        if (owner == null) {
555	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
556	        }
557	        this.clinicService.deleteOwner(owner);
558	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
564	        Owner owner = this.clinicService.findOwnerById(ownerId);
565	        if (owner == null) {
566	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
567	        }
568	        HttpHeaders headers = new HttpHeaders();
569	        Pet pet = petMapper.toPet(petFieldsDto);
570	        owner.setId(ownerId);
571	        pet.setOwner(owner);
572	        pet.getType().setName(null);
573	        this.clinicService.savePet(pet);
574	        PetDto petDto = petMapper.toPetDto(pet);
575	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
576	            .buildAndExpand(pet.getId()).toUri());
577	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
578	    }
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Override
582	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
583	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
584	        if (currentOwner != null) {
585	            Pet currentPet = this.clinicService.findPetById(petId);
586	            if (currentPet != null) {
587	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
588	                currentPet.setName(petFieldsDto.getName());
589	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
590	                this.clinicService.savePet(currentPet);
591	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
592	            }
593	        }
594	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
595	    }
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
600	        HttpHeaders headers = new HttpHeaders();
601	        Visit visit = visitMapper.toVisit(visitFieldsDto);
602	        Pet pet = new Pet();
603	        pet.setId(petId);
604	        visit.setPet(pet);
605	        this.clinicService.saveVisit(visit);
606	        VisitDto visitDto = visitMapper.toVisitDto(visit);
607	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
608	            .buildAndExpand(visit.getId()).toUri());
609	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
610	    }
611	
612	
613	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
614	    @Override
615	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
616	        Owner owner = this.clinicService.findOwnerById(ownerId);
617	        if (owner != null) {
618	            Pet pet = owner.getPet(petId);
619	            if (pet != null) {
620	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
621	            }
622	        }
623	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
624	    }
