18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
161	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
162	                .map(FieldError::getField)
163	                .distinct()
164	                .toList());
165	            return ResponseEntity.status(status).body(detail);
166	        }
167	        return ResponseEntity.status(status).body(detail);
168	    }
169	
170	    /**
171	     * Handles {@link MissingOwnerFieldsException} thrown when an owner is created or updated
172	     * with one or more required fields missing or blank. Returns a 400 Bad Request whose body
173	     * carries an {@code errors} array listing the name of each offending field.
174	     *
175	     * @param e The {@link MissingOwnerFieldsException} to be handled
176	     * @param request {@link HttpServletRequest} object referring to the current request.
177	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
178	     */
179	    @ExceptionHandler(MissingOwnerFieldsException.class)
180	    @ResponseBody
181	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
182	        logger.debug("Missing owner fields at {} {}: {}",
183	            request.getMethod(),
184	            request.getRequestURI(),
185	            e.getErrors());
186	        HttpStatus status = HttpStatus.BAD_REQUEST;
187	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
188	        detail.setProperty("errors", e.getErrors());
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	    /**
193	     * Handles {@link InvalidTelephoneException} thrown when an owner is created with a telephone
194	     * that cannot be normalized to valid E.164 form (a '+' followed by 8 to 15 digits).
195	     * Returns a 400 Bad Request whose body carries an {@code errors} array naming the offending
196	     * {@code telephone} field.
197	     *
198	     * @param e The {@link InvalidTelephoneException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
201	     */
202	    @ExceptionHandler(InvalidTelephoneException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
205	        logger.debug("Invalid owner telephone at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getRejectedValue());
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", List.of("telephone"));
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles {@link InvalidEmailException} thrown when an owner is created or updated with an
217	     * email that is present but not a syntactically valid address. Returns a 400 Bad Request whose
218	     * body carries an {@code errors} array naming the offending {@code email} field.
219	     *
220	     * @param e The {@link InvalidEmailException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
223	     */
224	    @ExceptionHandler(InvalidEmailException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
227	        logger.debug("Invalid owner email at {} {}: {}",
228	            request.getMethod(),
229	            request.getRequestURI(),
230	            e.getRejectedValue());
231	        HttpStatus status = HttpStatus.BAD_REQUEST;
232	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
233	        detail.setProperty("errors", List.of("email"));
234	        return ResponseEntity.status(status).body(detail);
235	    }
236	
237	    /**
238	     * Handles {@link DuplicateIdentityException} thrown when an owner is created whose whole derived
239	     * {@code identityKey} (normalized telephone, email and householdId joined together) exactly
240	     * matches that of an existing owner. This single check subsumes the former separate telephone,
241	     * email and household duplicate rules. Returns a 409 Conflict whose body carries an
242	     * {@code errors} array naming the offending {@code identityKey} field.
243	     *
244	     * @param e The {@link DuplicateIdentityException} to be handled
245	     * @param request {@link HttpServletRequest} object referring to the current request.
246	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
247	     */
248	    @ExceptionHandler(DuplicateIdentityException.class)
249	    @ResponseBody
250	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
251	        logger.debug("Duplicate owner identityKey at {} {}: {}",
252	            request.getMethod(),
253	            request.getRequestURI(),
254	            e.getRejectedValue());
255	        HttpStatus status = HttpStatus.CONFLICT;
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
257	        detail.setProperty("errors", List.of("identityKey"));
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link CityAtCapacityException} thrown when an owner is created whose city already
263	     * contains the maximum number of owners. Returns a 409 Conflict whose body carries an
264	     * {@code errors} array naming the offending {@code city} field.
265	     *
266	     * @param e The {@link CityAtCapacityException} to be handled
267	     * @param request {@link HttpServletRequest} object referring to the current request.
268	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
269	     */
270	    @ExceptionHandler(CityAtCapacityException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
273	        logger.debug("City at capacity at {} {}: {}",
274	            request.getMethod(),
275	            request.getRequestURI(),
276	            e.getCity());
277	        HttpStatus status = HttpStatus.CONFLICT;
278	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
279	        detail.setProperty("errors", List.of("city"));
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Handles {@link DailyOwnerLimitException} thrown when an owner is created after the maximum
285	     * number of owners for the current day has already been reached. Returns a 429 Too Many Requests
286	     * whose body carries an {@code errors} array naming the offending {@code registrationDate} field.
287	     *
288	     * @param e The {@link DailyOwnerLimitException} to be handled
289	     * @param request {@link HttpServletRequest} object referring to the current request.
290	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
291	     */
292	    @ExceptionHandler(DailyOwnerLimitException.class)
293	    @ResponseBody
294	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
295	        logger.debug("Daily owner limit reached at {} {}: {}",
296	            request.getMethod(),
297	            request.getRequestURI(),
298	            e.getDate());
299	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
300	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
301	        detail.setProperty("errors", List.of("registrationDate"));
302	        return ResponseEntity.status(status).body(detail);
303	    }
304	
305	}
